  async prePopulateAllProductsForOffline() {
    // Phase 4: i18n estático / Supabase product_translations.
    // Los productos ya vienen traducidos desde Supabase y almacenados en IndexedDB via ProductDataAdapter.
    Logger.info('[TranslationService] Pre-populate skipped — usando product_translations de Supabase');
    return;
  }


